const daAdmissionStructuralRowsBase64 = ""

type daAdmissionCandidateFixture struct {
	admission                                *DAAdmission
	raw, txBytes, payload                    []byte
	txid, wtxid, daID, commitment, chunkHash [32]byte
	fee                                      consensus.Uint128
	inputs                                   []consensus.Outpoint
	chunkCount, chunkIndex                   uint16
	kind                                     uint8
}

type daAdmissionCandidateFixtureValues struct {
	commitCount         uint16
	chunkIndex          uint16
	chunkPayload        []byte
	inputValues         []uint64
	inputOrder          []int
	outputValue         uint64
	fee                 consensus.Uint128
	onlyCommitment      bool
	commitmentAfterP2PK bool
}

func daAdmissionSlice[T any](value []T) [4]uintptr {
	var nilValue, firstElement uintptr
	if value == nil {
		nilValue = 1
	}
	if len(value) != 0 {
		firstElement = reflect.ValueOf(value).Pointer()
	}
	return [4]uintptr{nilValue, uintptr(len(value)), uintptr(cap(value)), firstElement}
}

func cloneDAAdmissionTx(tx *consensus.Tx) *consensus.Tx {
	if tx == nil {
		return nil
	}
	clone := *tx
	if tx.DaCommitCore != nil {
		core := *tx.DaCommitCore
		core.BatchSig = slices.Clone(core.BatchSig)
		clone.DaCommitCore = &core
	}
	if tx.DaChunkCore != nil {
		core := *tx.DaChunkCore
		clone.DaChunkCore = &core
	}
	clone.Inputs = slices.Clone(tx.Inputs)
	for i := range clone.Inputs {
		clone.Inputs[i].ScriptSig = slices.Clone(tx.Inputs[i].ScriptSig)
	}
	clone.Outputs = slices.Clone(tx.Outputs)
	for i := range clone.Outputs {
		clone.Outputs[i].CovenantData = slices.Clone(tx.Outputs[i].CovenantData)
	}
	clone.Witness = slices.Clone(tx.Witness)
	for i := range clone.Witness {
		clone.Witness[i].Pubkey, clone.Witness[i].Signature = slices.Clone(tx.Witness[i].Pubkey), slices.Clone(tx.Witness[i].Signature)
	}
	clone.DaPayload = slices.Clone(tx.DaPayload)
	return &clone
}

func daAdmissionTxSlices(tx *consensus.Tx) [][4]uintptr {
	if tx == nil {
		return nil
	}
	images := [][4]uintptr{daAdmissionSlice(tx.Inputs), daAdmissionSlice(tx.Outputs), daAdmissionSlice(tx.Witness), daAdmissionSlice(tx.DaPayload)}
	if tx.DaCommitCore != nil {
		images = append(images, daAdmissionSlice(tx.DaCommitCore.BatchSig))
	}
	for i := range tx.Inputs {
		images = append(images, daAdmissionSlice(tx.Inputs[i].ScriptSig))
	}
	for i := range tx.Outputs {
		images = append(images, daAdmissionSlice(tx.Outputs[i].CovenantData))
	}
	for i := range tx.Witness {
		images = append(images, daAdmissionSlice(tx.Witness[i].Pubkey), daAdmissionSlice(tx.Witness[i].Signature))
	}
	return images
}

func cloneDAAdmissionOwner(owner *PendingOutpointOwner) *PendingOutpointOwner {
	owner.mu.Lock()
	defer owner.mu.Unlock()
	image := &PendingOutpointOwner{tokenHighWater: owner.tokenHighWater, generation: owner.generation, inTransition: owner.inTransition, stableTip: owner.stableTip}
	if owner.byToken != nil {
		image.byToken = make(map[PendingOutpointToken]*pendingOutpointClaim, len(owner.byToken))
		for token, claim := range owner.byToken {
			cloned := *claim
			cloned.inputs = slices.Clone(claim.inputs)
			image.byToken[token] = &cloned
		}
	}
	if owner.byOutpoint != nil {
		image.byOutpoint = make(map[consensus.Outpoint]pendingOutpointRow, len(owner.byOutpoint))
		for outpoint, row := range owner.byOutpoint {
			image.byOutpoint[outpoint] = row
		}
	}
	return image
}

func captureDAAdmissionPurity(admission *DAAdmission) []any {
	snapshot := admission.snapshot
	snapshot.TxBytes, snapshot.Inputs = slices.Clone(snapshot.TxBytes), slices.Clone(snapshot.Inputs)
	marshaled, err := consensus.MarshalTx(admission.tx)
	var commitCore *consensus.DaCommitCore
	var chunkCore *consensus.DaChunkCore
	if admission.tx != nil {
		commitCore, chunkCore = admission.tx.DaCommitCore, admission.tx.DaChunkCore
	}
	return []any{
		reflect.ValueOf(admission).Pointer(), reflect.ValueOf(admission.self).Pointer(), reflect.ValueOf(admission.guard).Pointer(), reflect.ValueOf(admission.guard.owner).Pointer(), reflect.ValueOf(admission.guard.chainState).Pointer(), reflect.ValueOf(admission.tx).Pointer(), reflect.ValueOf(commitCore).Pointer(), reflect.ValueOf(chunkCore).Pointer(),
		snapshot, admission.Snapshot(), daAdmissionSlice(admission.snapshot.TxBytes), daAdmissionSlice(admission.snapshot.Inputs), admission.context, admission.guard.state.Load(),
		cloneDAAdmissionTx(admission.tx), daAdmissionTxSlices(admission.tx), cloneDAAdmissionOwner(admission.guard.owner), cloneChainState(admission.guard.chainState), marshaled, err == nil,
	}
}

func requireDAAdmissionStructure(t *testing.T) {
	type sourceScope struct {
		start, end token.Pos
		identity   string
		symbol     string
	}
	contexts := []build.Context{build.Default, build.Default, build.Default}
	contexts[1].GOOS, contexts[1].GOARCH = "darwin", "arm64"
	contexts[2].GOOS, contexts[2].GOARCH = "linux", "amd64"
	var selectedFiles string
	for _, context := range contexts {
		if !context.CgoEnabled || len(context.BuildTags) != 0 {
			t.Fatalf("build context=%s/%s cgo=%v tags=%v", context.GOOS, context.GOARCH, context.CgoEnabled, context.BuildTags)
		}
		fset, files, sources := token.NewFileSet(), map[string]*ast.File{}, map[string][]byte{}
		var selection []string
		for _, spec := range []struct {
			name, dir         string
			goFiles, cgoFiles int
		}{{"node", ".", 62, 0}, {"consensus", "../consensus", 59, 3}} {
			pkg, err := context.ImportDir(spec.dir, 0)
			if err != nil {
				t.Fatal(err)
			}
			if len(pkg.GoFiles) != spec.goFiles || len(pkg.CgoFiles) != spec.cgoFiles {
				t.Fatalf("%s/%s %s files=Go:%d Cgo:%d", context.GOOS, context.GOARCH, spec.name, len(pkg.GoFiles), len(pkg.CgoFiles))
			}
			names := append(slices.Clone(pkg.GoFiles), pkg.CgoFiles...)
			sort.Strings(names)
			selection = append(selection, spec.name+"="+strings.Join(names, ","))
			for _, name := range names {
				key, path := spec.name+"/"+name, filepath.Join(spec.dir, name)
				source, err := os.ReadFile(path)
				if err != nil {
					t.Fatal(err)
				}
				files[key], err = parser.ParseFile(fset, path, source, 0)
				if err != nil {
					t.Fatal(err)
				}
				sources[key] = source
			}
		}
		currentSelection := strings.Join(selection, "|")
		if selectedFiles == "" {
			selectedFiles = currentSelection
		} else if currentSelection != selectedFiles {
			t.Fatalf("build-selected files differ for %s/%s", context.GOOS, context.GOARCH)
		}
		if files["node/da_admission.go"] == nil || files["node/da_relay_owner.go"] == nil {
			t.Fatal("allowed production files omitted by build context")
		}
		functions, definitions, callFun, scopes := map[string]bool{}, map[token.Pos]bool{}, map[token.Pos]bool{}, map[string][]sourceScope{}
		for key, file := range files {
			ast.Inspect(file, func(node ast.Node) bool {
				switch node := node.(type) {
				case *ast.FuncDecl:
					functions[node.Name.Name], definitions[node.Name.Pos()] = true, true
					scopes[key] = append(scopes[key], sourceScope{node.Pos(), node.End(), key + ":" + node.Name.Name, node.Name.Name})
				case *ast.ValueSpec:
					for _, name := range node.Names {
						definitions[name.Pos()] = true
						scopes[key] = append(scopes[key], sourceScope{node.Pos(), node.End(), key + ":" + name.Name, name.Name})
					}
				case *ast.FuncLit:
					position := fset.Position(node.Pos()).String()
					scopes[key] = append(scopes[key], sourceScope{node.Pos(), node.End(), key + ":lit:" + position, "lit:" + position})
				case *ast.CallExpr:
					ast.Inspect(node.Fun, func(child ast.Node) bool {
						if id, ok := child.(*ast.Ident); ok {
							callFun[id.Pos()] = true
						}
						return true
					})
				}
				return true
			})
		}
		got, where, edges, allowed := map[string]int{}, map[string]string{}, map[string]map[string]bool{}, map[string]bool{}
		add := func(row string, pos token.Pos) { got[row]++; where[row] = fset.Position(pos).String() }
		targets := map[string]bool{"ParseTx": true, "parseDAAdmission": true, "parseRelayMetadataTx": true, "parseRetainedDAMember": true, "renderDARelayAdmissionCandidate": true, "AdmitDA": true, "Lookup" + "RetainedTx": true}
		for key, file := range files {
			selected := key == "node/da_admission.go" || key == "node/da_relay_owner.go"
			if selected {
				for _, scope := range scopes[key] {
					allowed[scope.symbol] = true
				}
			}
			ast.Inspect(file, func(node ast.Node) bool {
				if node == nil {
					return true
				}
				scope := sourceScope{identity: key + ":file", symbol: "file"}
				for _, candidate := range scopes[key] {
					if candidate.start <= node.Pos() && node.End() <= candidate.end {
						scope = candidate
					}
				}
				if id, ok := node.(*ast.Ident); ok && targets[id.Name] {
					category := "value"
					if definitions[id.Pos()] {
						category = "decl"
					} else {
						if callFun[id.Pos()] {
							category = "call"
						}
						if edges[scope.symbol] == nil {
							edges[scope.symbol] = map[string]bool{}
						}
						edges[scope.symbol][id.Name] = true
					}
					add("edge-"+category+"|"+scope.identity+"|"+id.Name, id.Pos())
				}
				if !selected {
					return true
				}
				category := ""
				switch node := node.(type) {
				case *ast.FuncDecl:
					category = "declaration"
				case *ast.GenDecl, *ast.ValueSpec:
					category = "gen"
				case *ast.CallExpr:
					category = "call"
				case *ast.AssignStmt, *ast.IncDecStmt:
					category = "write"
				case *ast.FuncLit:
					category = "funclit"
				case *ast.GoStmt:
					category = "go"
				case *ast.DeferStmt:
					category = "defer"
				case *ast.ImportSpec:
					category = "import"
				case *ast.SelectorExpr:
					category = "field"
				case *ast.Ident:
					category = "read"
					if functions[node.Name] && !callFun[node.Pos()] && !definitions[node.Pos()] {
						category = "value"
					}
				}
				if category != "" {
					start, end := fset.Position(node.Pos()).Offset, fset.Position(node.End()).Offset
					add(category+"|"+scope.identity+"|"+string(sources[key][start:end]), node.Pos())
				}
				return true
			})
		}
		var reachesParse func(string, map[string]bool) bool
		reachesParse = func(name string, seen map[string]bool) bool {
			if name == "ParseTx" {
				return true
			}
			if seen[name] {
				return false
			}
			seen[name] = true
			for target := range edges[name] {
				if reachesParse(target, seen) {
					return true
				}
			}
			return false
		}
		var capable []string
		for name := range allowed {
			if reachesParse(name, map[string]bool{}) {
				capable = append(capable, name)
			}
		}
		sort.Strings(capable)
		if strings.Join(capable, ",") != "BeginDAAdmission,parseDAAdmission" {
			t.Fatalf("parse-capable allowed declarations=%v", capable)
		}
		encodedRows, err := base64.StdEncoding.DecodeString(daAdmissionStructuralRowsBase64)
		if err != nil {
			t.Fatal(err)
		}
		want := map[string]int{}
		for _, row := range strings.Split(string(encodedRows), "\x1e") {
			if row != "" {
				want[row]++
			}
		}
		for row, count := range got {
			if want[row] != count {
				t.Fatalf("structural row %q count=%d want=%d at %s", row, count, want[row], where[row])
			}
		}
		for row, count := range want {
			if got[row] != count {
				t.Fatalf("missing structural row %q count=%d want=%d", row, got[row], count)
			}
		}
	}
}

func newDAAdmissionCandidateFixture(t *testing.T, kind uint8, values ...daAdmissionCandidateFixtureValues) daAdmissionCandidateFixture {
	t.Helper()
	if len(values) > 1 {
		t.Fatal("multiple DA admission fixture values")
	}
	value := daAdmissionCandidateFixtureValues{
		commitCount:  uint16(consensus.MAX_DA_CHUNK_COUNT),
		chunkIndex:   1,
		chunkPayload: []byte("RUB-1273 chunk payload"),
		inputValues:  []uint64{1_000_000, 1_000_000},
		inputOrder:   []int{1, 0},
		outputValue:  1_400_000,
		fee:          consensus.Uint128{Lo: 600_000},
	}
	if len(values) == 1 {
		value = values[0]
	}
	if value.inputValues == nil {
		value.inputValues = []uint64{1_000_000, 1_000_000}
	}
	if value.inputOrder == nil {
		value.inputOrder = []int{1, 0}
	}
	if value.fee.IsZero() {
		value.fee = consensus.Uint128{Lo: 600_000}
	}
	if value.outputValue == 0 && !value.onlyCommitment {
		value.outputValue = 1_400_000
	}
	signer := mustNodeMLDSA87Keypair(t)
	address := consensus.P2PKCovenantDataForPubkey(signer.PubkeyBytes())
	state, outpoints := testSpendableChainState(address, value.inputValues)
	cfg := DefaultMempoolConfig()
	cfg.PolicyMaxDaBytesPerBlock = consensus.MAX_DA_BYTES_PER_BLOCK
	mp, err := NewMempoolWithConfig(state, nil, devnetGenesisChainID, cfg)
	if err != nil {
		t.Fatalf("NewMempool: %v", err)
	}
	inputs := make([]consensus.Outpoint, len(value.inputOrder))
	for i, index := range value.inputOrder {
		if index < 0 || index >= len(outpoints) {
			t.Fatalf("input order[%d]=%d outside %d inputs", i, index, len(outpoints))
		}
		inputs[i] = outpoints[index]
	}
	txInputs := make([]consensus.TxInput, len(inputs))
	for i, input := range inputs {
		txInputs[i] = consensus.TxInput{PrevTxid: input.Txid, PrevVout: input.Vout, Sequence: uint32(i + 3)}
	}
	daID := [32]byte{0xa1, 0xb2, 0xc3}
	commitment := sha3.Sum256([]byte("RUB-1273 payload commitment"))
	tx := &consensus.Tx{Version: 1, TxKind: kind, TxNonce: 37, Inputs: txInputs, Locktime: 41}
	fixture := daAdmissionCandidateFixture{fee: value.fee, inputs: append([]consensus.Outpoint(nil), inputs...), daID: daID, commitment: commitment, kind: kind}
	switch kind {
	case 0x01:
		if value.commitCount == 0 {
			value.commitCount = uint16(consensus.MAX_DA_CHUNK_COUNT)
		}
		fixture.chunkCount = value.commitCount
		commitOutput := consensus.TxOutput{CovenantType: consensus.COV_TYPE_DA_COMMIT, CovenantData: append([]byte(nil), commitment[:]...)}
		if value.onlyCommitment {
			tx.Outputs = []consensus.TxOutput{commitOutput}
		} else {
			p2pkOutput := consensus.TxOutput{Value: value.outputValue, CovenantType: consensus.COV_TYPE_P2PK, CovenantData: append([]byte(nil), address...)}
			if value.commitmentAfterP2PK {
				tx.Outputs = []consensus.TxOutput{p2pkOutput, commitOutput}
			} else {
				tx.Outputs = []consensus.TxOutput{commitOutput, p2pkOutput}
			}
		}
		tx.DaPayload = []byte("RUB-1273 manifest")
		tx.DaCommitCore = &consensus.DaCommitCore{DaID: daID, ChunkCount: fixture.chunkCount, BatchNumber: 7}
	case 0x02:
		if value.chunkPayload == nil {
			value.chunkPayload = []byte("RUB-1273 chunk payload")
		}
		fixture.chunkIndex = value.chunkIndex
		fixture.payload = append([]byte(nil), value.chunkPayload...)
		fixture.chunkHash = sha3.Sum256(value.chunkPayload)
		tx.Outputs = []consensus.TxOutput{{Value: value.outputValue, CovenantType: consensus.COV_TYPE_P2PK, CovenantData: append([]byte(nil), address...)}}
		tx.DaPayload = append([]byte(nil), value.chunkPayload...)
		tx.DaChunkCore = &consensus.DaChunkCore{DaID: daID, ChunkIndex: fixture.chunkIndex, ChunkHash: fixture.chunkHash}
	default:
		t.Fatalf("unsupported test kind %#x", kind)
	}
	if err := consensus.SignTransaction(tx, state.Utxos, devnetGenesisChainID, signer); err != nil {
		t.Fatalf("SignTransaction: %v", err)
	}
	raw := mustMarshalTxForNodeTest(t, tx)
	_, txid, wtxid, consumed, err := consensus.ParseTx(raw)
	if err != nil || consumed != len(raw) {
		t.Fatalf("independent ParseTx=(%d,%v), want %d,nil", consumed, err, len(raw))
	}
	fixture.txid, fixture.wtxid = txid, wtxid
	fixture.raw = append([]byte(nil), raw...)
	fixture.txBytes = append([]byte(nil), raw...)
	fixture.admission, err = mp.BeginDAAdmission(fixture.raw)
	if err != nil {
		t.Fatalf("BeginDAAdmission: %v", err)
	}
	return fixture
}

func requireDAAdmissionCandidate(t *testing.T, got daRelayAdmissionCandidate, want daAdmissionCandidateFixture, provenance daProvenance) {
	t.Helper()
	wantLocator := daRelayLocator{daID: want.daID, kind: daRelayLocatorCommit}
	if want.kind == 0x02 {
		wantLocator.kind, wantLocator.chunkIndex = daRelayLocatorChunk, want.chunkIndex
	}
	if got.member.locator != wantLocator || got.member.member.txid != want.txid || got.member.member.wtxid != want.wtxid ||
		got.member.member.fee != want.fee || got.member.member.provenance != provenance || got.member.member.token != (PendingOutpointToken{}) ||
		!slices.Equal(got.member.member.inputs, want.inputs) || !bytes.Equal(got.member.txBytes, want.txBytes) {
		t.Fatalf("candidate identity mismatch: locator=%+v want=%+v txid=%x/%x wtxid=%x/%x fee=%s/%s inputs=%v provenance=%+v", got.member.locator, wantLocator, got.member.member.txid, want.txid, got.member.member.wtxid, want.wtxid, got.member.member.fee.String(), want.fee.String(), slices.Equal(got.member.member.inputs, want.inputs), got.member.member.provenance)
	}
	if err := got.member.validate(); err != nil {
		t.Fatalf("candidate member shape: %v", err)
	}
	if want.kind == 0x01 {
		if len(got.member.payload) != 0 || got.payloadCommitment != want.commitment || got.chunkCount != want.chunkCount || got.chunkHash != ([32]byte{}) {
			t.Fatalf("commit candidate mismatch: payload=%d commitment=%x/%x count=%d/%d hash=%x", len(got.member.payload), got.payloadCommitment, want.commitment, got.chunkCount, want.chunkCount, got.chunkHash)
		}
		return
	}
	if !bytes.Equal(got.member.payload, want.payload) || got.chunkHash != want.chunkHash || got.payloadCommitment != ([32]byte{}) || got.chunkCount != 0 {
		t.Fatalf("chunk candidate mismatch: payload_match=%v hash=%x/%x commitment=%x count=%d", bytes.Equal(got.member.payload, want.payload), got.chunkHash, want.chunkHash, got.payloadCommitment, got.chunkCount)
	}
}

func requireDAAdmissionCandidateError(t *testing.T, admission *DAAdmission, provenance daProvenance, want error) {
	t.Helper()
	before := captureDAAdmissionPurity(admission)
	got, err := admission.renderDARelayAdmissionCandidate(provenance)
	after := captureDAAdmissionPurity(admission)
	if !errors.Is(err, want) || err != want || !reflect.DeepEqual(got, daRelayAdmissionCandidate{}) || !reflect.DeepEqual(after, before) { //nolint:errorlint // Contract requires the existing direct sentinel, not a wrapper.
		var kind any = "nil"
		if admission.tx != nil {
			kind = admission.tx.TxKind
		}
		t.Fatalf("render tx_kind=%v err=%v want=%v zero=%v pure=%v", kind, err, want, reflect.DeepEqual(got, daRelayAdmissionCandidate{}), reflect.DeepEqual(after, before))
	}
}

func mustDAAdmissionCandidate(t *testing.T, admission *DAAdmission, provenance daProvenance) daRelayAdmissionCandidate {
	t.Helper()
	before := captureDAAdmissionPurity(admission)
	candidate, err := admission.renderDARelayAdmissionCandidate(provenance)
	if err != nil {
		t.Fatalf("render: %v", err)
	}
	if !reflect.DeepEqual(captureDAAdmissionPurity(admission), before) {
		t.Fatal("successful render changed complete admission, owner, or chainstate image")
	}
	return candidate
}

func TestDAAdmissionCandidateClosedDomain(t *testing.T) {
	fixture := newDAAdmissionCandidateFixture(t, 0x01)
	defer fixture.admission.Close()
	tuples := 0
	for kind := uint16(0); kind <= uint16(^uint8(0)); kind++ {
		for identities := uint8(0); identities < 4; identities++ {
			value := daProvenance{kind: daProvenanceKind(kind)}
			if identities&1 != 0 {
				value.peerIdentity = "peer"
			}
			if identities&2 != 0 {
				value.quotaIdentity = "quota"
			}
			tuples++
			valid := value.kind == daProvenancePeer && identities == 3 ||
				(value.kind == daProvenanceLocal || value.kind == daProvenanceDetachedReorg) && identities == 0
			if valid {
				got := mustDAAdmissionCandidate(t, fixture.admission, value)
				wantQuota := ""
				if value.kind == daProvenancePeer {
					wantQuota = "quota"
				}
				if got.member.member.provenance.quotaKey() != wantQuota {
					t.Fatalf("kind=%#x identities=%d quota=%q", kind, identities, got.member.member.provenance.quotaKey())
				}
				requireDAAdmissionCandidate(t, got, fixture, value)
			} else {
				requireDAAdmissionCandidateError(t, fixture.admission, value, errDAProvenanceInvalid)
			}
		}
	}
	if tuples != 256*4 {
		t.Fatalf("provenance tuples=%d, want 1024", tuples)
	}
	copy := *fixture.admission
	mustPanic(t, func() { _, _ = copy.renderDARelayAdmissionCandidate(daProvenance{kind: daProvenanceLocal}) })
	var nilAdmission *DAAdmission
	mustPanic(t, func() { _, _ = nilAdmission.renderDARelayAdmissionCandidate(daProvenance{kind: daProvenanceLocal}) })
	resolved := newDAAdmissionCandidateFixture(t, 0x01)
	resolved.admission.guard.state.Store(daAdmissionResolved)
	mustPanic(t, func() {
		_, _ = resolved.admission.renderDARelayAdmissionCandidate(daProvenance{kind: daProvenanceLocal})
	})
	resolved.admission.Close()
	mustPanic(t, func() {
		_, _ = resolved.admission.renderDARelayAdmissionCandidate(daProvenance{kind: daProvenanceLocal})
	})
}

func TestDAAdmissionCandidateRoleMatrix(t *testing.T) {
	provenance := daProvenance{kind: daProvenancePeer, peerIdentity: "peer", quotaIdentity: "quota"}
	for _, kind := range []uint8{0x01, 0x02} {
		fixture := newDAAdmissionCandidateFixture(t, kind)
		got := mustDAAdmissionCandidate(t, fixture.admission, provenance)
		requireDAAdmissionCandidate(t, got, fixture, provenance)
		fixture.admission.Close()
	}
	for _, tc := range []struct {
		name   string
		kind   uint8
		mutate func(*daRelayAdmissionCandidate)
		want   error
	}{
		{"commit payload", 0x01, func(candidate *daRelayAdmissionCandidate) { candidate.member.payload = []byte{1} }, errDARelayMemberIncomplete},
		{"commit index", 0x01, func(candidate *daRelayAdmissionCandidate) { candidate.member.locator.chunkIndex = 1 }, errDARelayMemberIncomplete},
		{"commit chunk hash", 0x01, func(candidate *daRelayAdmissionCandidate) { candidate.chunkHash = [32]byte{1} }, errDARelayMemberIncomplete},
		{"commit zero count", 0x01, func(candidate *daRelayAdmissionCandidate) { candidate.chunkCount = 0 }, errDARelayChunkCountInvalid},
		{"chunk commitment", 0x02, func(candidate *daRelayAdmissionCandidate) { candidate.payloadCommitment = [32]byte{1} }, errDARelayMemberIncomplete},
		{"chunk count", 0x02, func(candidate *daRelayAdmissionCandidate) { candidate.chunkCount = 1 }, errDARelayMemberIncomplete},
		{"chunk oversized payload", 0x02, func(candidate *daRelayAdmissionCandidate) {
			candidate.member.payload = make([]byte, consensus.CHUNK_BYTES+1)
		}, errDARelayChunkPayloadSizeInvalid},
		{"token", 0x01, func(candidate *daRelayAdmissionCandidate) {
			candidate.member.member.token = PendingOutpointToken{seq: 1}
		}, errDARelayMemberIncomplete},
	} {
		t.Run(tc.name, func(t *testing.T) {
			fixture := newDAAdmissionCandidateFixture(t, tc.kind)
			candidate := mustDAAdmissionCandidate(t, fixture.admission, provenance)
			tc.mutate(&candidate)
			if err := candidate.validate(); !errors.Is(err, tc.want) || err != tc.want { //nolint:errorlint // Contract requires the existing direct sentinel, not a wrapper.
				t.Fatalf("candidate validate=%v, want %v", err, tc.want)
			}
			fixture.admission.Close()
		})
	}
	for _, tc := range []struct {
		name  string
		kind  uint8
		value daAdmissionCandidateFixtureValues
	}{
		{"commit count one", 0x01, daAdmissionCandidateFixtureValues{commitCount: 1}},
		{"commit count maximum", 0x01, daAdmissionCandidateFixtureValues{commitCount: uint16(consensus.MAX_DA_CHUNK_COUNT)}},
		{"commit full u128 fee", 0x01, daAdmissionCandidateFixtureValues{
			commitCount:    1,
			inputValues:    []uint64{1 << 63, 1 << 63},
			inputOrder:     []int{1, 0},
			fee:            consensus.Uint128{Hi: 1},
			onlyCommitment: true,
		}},
		{"commit one ordered input", 0x01, daAdmissionCandidateFixtureValues{
			commitCount: 1,
			inputValues: []uint64{1_000_000},
			inputOrder:  []int{0},
			outputValue: 400_000,
		}},
		// One signed ML-DSA witness consumes 7,227 bytes; 13 is the largest
		// count within MAX_WITNESS_BYTES_PER_TX (including the count varint).
		{"commit thirteen ordered inputs", 0x01, daAdmissionCandidateFixtureValues{
			commitCount: 1,
			inputValues: []uint64{
				1_000_000, 1_000_000, 1_000_000, 1_000_000, 1_000_000, 1_000_000, 1_000_000,
				1_000_000, 1_000_000, 1_000_000, 1_000_000, 1_000_000, 1_000_000,
			},
			inputOrder:  []int{12, 0, 11, 1, 10, 2, 9, 3, 8, 4, 7, 5, 6},
			outputValue: 12_400_000,
		}},
		{"commitment after p2pk", 0x01, daAdmissionCandidateFixtureValues{
			commitCount:         1,
			commitmentAfterP2PK: true,
		}},
		{"chunk index zero", 0x02, daAdmissionCandidateFixtureValues{chunkIndex: 0, chunkPayload: []byte("RUB-1273 chunk payload")}},
		{"chunk index maximum", 0x02, daAdmissionCandidateFixtureValues{chunkIndex: uint16(consensus.MAX_DA_CHUNK_COUNT - 1), chunkPayload: []byte("RUB-1273 chunk payload")}},
		{"chunk payload one", 0x02, daAdmissionCandidateFixtureValues{chunkIndex: 1, chunkPayload: []byte{1}}},
		{"chunk payload maximum", 0x02, daAdmissionCandidateFixtureValues{chunkIndex: 1, chunkPayload: make([]byte, consensus.CHUNK_BYTES)}},
	} {
		t.Run(tc.name, func(t *testing.T) {
			fixture := newDAAdmissionCandidateFixture(t, tc.kind, tc.value)
			candidate := mustDAAdmissionCandidate(t, fixture.admission, provenance)
			requireDAAdmissionCandidate(t, candidate, fixture, provenance)
			fixture.admission.Close()
		})
	}
	for _, tc := range []struct {
		name   string
		kind   uint8
		mutate func(*consensus.Tx)
		want   error
	}{
		{"commit nil core", 0x01, func(tx *consensus.Tx) { tx.DaCommitCore = nil }, errDARelayMemberIncomplete},
		{"commit conflicting core", 0x01, func(tx *consensus.Tx) { tx.DaChunkCore = &consensus.DaChunkCore{} }, errDARelayMemberIncomplete},
		{"commit zero count", 0x01, func(tx *consensus.Tx) { tx.DaCommitCore.ChunkCount = 0 }, errDARelayChunkCountInvalid},
		{"commit excessive count", 0x01, func(tx *consensus.Tx) { tx.DaCommitCore.ChunkCount = uint16(consensus.MAX_DA_CHUNK_COUNT + 1) }, errDARelayChunkCountInvalid},
		{"commit missing commitment", 0x01, func(tx *consensus.Tx) { tx.Outputs = tx.Outputs[1:] }, errDARelayMemberIncomplete},
		{"commit multiple commitments", 0x01, func(tx *consensus.Tx) {
			tx.Outputs = append(tx.Outputs, consensus.TxOutput{CovenantType: consensus.COV_TYPE_DA_COMMIT, CovenantData: make([]byte, 32)})
		}, errDARelayMemberIncomplete},
		{"commit short commitment", 0x01, func(tx *consensus.Tx) { tx.Outputs[0].CovenantData = make([]byte, 31) }, errDARelayMemberIncomplete},
		{"commit long commitment", 0x01, func(tx *consensus.Tx) { tx.Outputs[0].CovenantData = make([]byte, 33) }, errDARelayMemberIncomplete},
		{"chunk nil core", 0x02, func(tx *consensus.Tx) { tx.DaChunkCore = nil }, errDARelayMemberIncomplete},
		{"chunk conflicting core", 0x02, func(tx *consensus.Tx) { tx.DaCommitCore = &consensus.DaCommitCore{} }, errDARelayMemberIncomplete},
		{"chunk index out of range", 0x02, func(tx *consensus.Tx) { tx.DaChunkCore.ChunkIndex = uint16(consensus.MAX_DA_CHUNK_COUNT) }, errDARelayChunkIndexOutOfRange},
		{"chunk empty payload", 0x02, func(tx *consensus.Tx) { tx.DaPayload = nil }, errDARelayMemberIncomplete},
		{"chunk oversized payload", 0x02, func(tx *consensus.Tx) { tx.DaPayload = make([]byte, consensus.CHUNK_BYTES+1) }, errDARelayChunkPayloadSizeInvalid},
	} {
		t.Run(tc.name, func(t *testing.T) {
			fixture := newDAAdmissionCandidateFixture(t, tc.kind)
			tc.mutate(fixture.admission.tx)
			requireDAAdmissionCandidateError(t, fixture.admission, provenance, tc.want)
			fixture.admission.Close()
		})
	}
	t.Run("nil held parse", func(t *testing.T) {
		fixture := newDAAdmissionCandidateFixture(t, 0x01)
		fixture.admission.tx = nil
		requireDAAdmissionCandidateError(t, fixture.admission, provenance, errDARelayMemberIncomplete)
		fixture.admission.Close()
	})
	commit, chunk := newDAAdmissionCandidateFixture(t, 0x01), newDAAdmissionCandidateFixture(t, 0x02)
	defer commit.admission.Close()
	defer chunk.admission.Close()
	for _, shape := range []struct {
		name   string
		value  *daAdmissionCandidateFixture
		base   *consensus.Tx
		mutate func(*consensus.Tx)
	}{
		{"valid commit", &commit, commit.admission.tx, func(*consensus.Tx) {}},
		{"valid chunk", &chunk, chunk.admission.tx, func(*consensus.Tx) {}},
		{"commit zero count", &commit, commit.admission.tx, func(tx *consensus.Tx) { tx.DaCommitCore.ChunkCount = 0 }},
		{"chunk index maximum", &chunk, chunk.admission.tx, func(tx *consensus.Tx) { tx.DaChunkCore.ChunkIndex = uint16(consensus.MAX_DA_CHUNK_COUNT) }},
		{"chunk payload excessive", &chunk, chunk.admission.tx, func(tx *consensus.Tx) { tx.DaPayload = make([]byte, consensus.CHUNK_BYTES+1) }},
	} {
		t.Run("unsupported kind "+shape.name, func(t *testing.T) {
			for kind := uint16(0); kind <= uint16(^uint8(0)); kind++ {
				if uint8(kind) == 0x01 || uint8(kind) == 0x02 {
					continue
				}
				held := cloneDAAdmissionTx(shape.base)
				shape.mutate(held)
				held.TxKind = uint8(kind)
				shape.value.admission.tx = held
				requireDAAdmissionCandidateError(t, shape.value.admission, daProvenance{kind: daProvenanceLocal}, errDARelayMemberIncomplete)
				shape.value.admission.tx = shape.base
			}
		})
	}
}

func TestDAAdmissionCandidateUsesHeldParse(t *testing.T) {
	t.Run("retained commit parse", func(t *testing.T) {
		fixture := newDAAdmissionCandidateFixture(t, 0x01)
		defer fixture.admission.Close()
		commitmentOffset := bytes.Index(fixture.raw, fixture.commitment[:])
		if commitmentOffset < 0 {
			t.Fatal("serialized commitment missing")
		}
		fixture.raw[commitmentOffset] ^= 0xff
		snapshot := fixture.admission.Snapshot()
		snapshot.TxID[0] ^= 0xff
		snapshot.WTxID[0] ^= 0xff
		snapshot.TxBytes[0] ^= 0xff
		snapshot.Inputs[0].Vout++
		got := mustDAAdmissionCandidate(t, fixture.admission, daProvenance{kind: daProvenanceLocal})
		requireDAAdmissionCandidate(t, got, fixture, daProvenance{kind: daProvenanceLocal})
	})
	t.Run("held chunk hash", func(t *testing.T) {
		fixture := newDAAdmissionCandidateFixture(t, 0x02)
		defer fixture.admission.Close()
		wantHash := [32]byte{0xd4, 0xa1, 0x27}
		if wantHash == sha3.Sum256(fixture.payload) {
			t.Fatal("held chunk hash matches payload hash")
		}
		fixture.admission.tx.DaChunkCore.ChunkHash = wantHash
		fixture.chunkHash = wantHash
		got := mustDAAdmissionCandidate(t, fixture.admission, daProvenance{kind: daProvenanceLocal})
		requireDAAdmissionCandidate(t, got, fixture, daProvenance{kind: daProvenanceLocal})
	})
	t.Run("structural ownership", requireDAAdmissionStructure)
}

func TestDAAdmissionCandidateIsolation(t *testing.T) {
	fixture := newDAAdmissionCandidateFixture(t, 0x02)
	defer fixture.admission.Close()
	provenance := daProvenance{kind: daProvenancePeer, peerIdentity: "peer", quotaIdentity: "quota"}
	first := mustDAAdmissionCandidate(t, fixture.admission, provenance)
	second := mustDAAdmissionCandidate(t, fixture.admission, provenance)
	candidatePayloadOffset := bytes.Index(first.member.txBytes, first.member.payload)
	if candidatePayloadOffset < 0 {
		t.Fatal("candidate payload missing from retained bytes")
	}
	payloadByte, txPayloadByte := first.member.payload[0], first.member.txBytes[candidatePayloadOffset]
	first.member.payload[0] ^= 0xff
	if first.member.txBytes[candidatePayloadOffset] != txPayloadByte {
		t.Fatal("candidate payload aliases retained bytes")
	}
	first.member.payload[0] = payloadByte
	first.member.txBytes[candidatePayloadOffset] ^= 0xff
	if first.member.payload[0] != payloadByte {
		t.Fatal("candidate retained bytes alias payload")
	}
	first.member.txBytes[candidatePayloadOffset] = txPayloadByte
	payloadOffset := bytes.Index(fixture.raw, fixture.payload)
	if payloadOffset < 0 {
		t.Fatal("serialized chunk payload missing")
	}
	fixture.raw[payloadOffset] ^= 0xff
	snapshot := fixture.admission.Snapshot()
	snapshot.TxBytes[0] ^= 0xff
	snapshot.Inputs[0].Vout++
	fixture.admission.snapshot.TxBytes[0] ^= 0xff
	fixture.admission.snapshot.Inputs[0].Vout++
	fixture.admission.tx.DaPayload[0] ^= 0xff
	requireDAAdmissionCandidate(t, first, fixture, provenance)
	requireDAAdmissionCandidate(t, second, fixture, provenance)
	fixture.admission.snapshot.TxBytes[0] ^= 0xff
	fixture.admission.snapshot.Inputs[0].Vout--
	fixture.admission.tx.DaPayload[0] ^= 0xff
	first.member.txBytes[0] ^= 0xff
	first.member.payload[0] ^= 0xff
	first.member.member.inputs[0].Vout++
	requireDAAdmissionCandidate(t, second, fixture, provenance)
	third := mustDAAdmissionCandidate(t, fixture.admission, provenance)
	requireDAAdmissionCandidate(t, third, fixture, provenance)
	firstTxByte, firstPayloadByte, firstVout := first.member.txBytes[0], first.member.payload[0], first.member.member.inputs[0].Vout
	second.member.txBytes[0] ^= 0xff
	second.member.payload[0] ^= 0xff
	second.member.member.inputs[0].Vout++
	if first.member.txBytes[0] != firstTxByte || first.member.payload[0] != firstPayloadByte || first.member.member.inputs[0].Vout != firstVout {
		t.Fatal("second candidate aliases first candidate")
	}
	after := fixture.admission.Snapshot()
	if !bytes.Equal(after.TxBytes, fixture.txBytes) || !slices.Equal(after.Inputs, fixture.inputs) {
		t.Fatal("candidate mutation changed admission")
	}
}

func TestDAAdmissionCandidateErrorOrder(t *testing.T) {
	provenance := daProvenance{kind: daProvenancePeer}
	success := newDAAdmissionCandidateFixture(t, 0x01)
	candidate := mustDAAdmissionCandidate(t, success.admission, daProvenance{kind: daProvenanceLocal})
	requireDAAdmissionCandidate(t, candidate, success, daProvenance{kind: daProvenanceLocal})
	success.admission.Close()

	fixture := newDAAdmissionCandidateFixture(t, 0x01)
	fixture.admission.tx.DaCommitCore.ChunkCount = 0
	fixture.admission.tx.Outputs = nil
	fixture.admission.tx = nil
	requireDAAdmissionCandidateError(t, fixture.admission, provenance, errDAProvenanceInvalid)
	fixture.admission.Close()

	invalidKind := newDAAdmissionCandidateFixture(t, 0x01)
	invalidKind.admission.tx.TxKind = 0x03
	invalidKind.admission.tx.DaCommitCore.ChunkCount = 0
	invalidKind.admission.tx.Outputs = nil
	requireDAAdmissionCandidateError(t, invalidKind.admission, daProvenance{kind: daProvenanceLocal}, errDARelayMemberIncomplete)
	invalidKind.admission.Close()

	closed := newDAAdmissionCandidateFixture(t, 0x01)
	closed.admission.Close()
	mustPanic(t, func() { _, _ = closed.admission.renderDARelayAdmissionCandidate(provenance) })
}
